// Cut Glass - relief (displacement) v2. STATIC (no t/u_time). Runs INSIDE map().
// Hammered-glass look = dense pattern of sharp-edged micro-facets, produced by a
// 3D Voronoi (F1: distance to the nearest cell). In scope: d_surf, p, pModel.
//
// SPEED. map() runs 4 times per marching step and a ray that misses the object
// takes ~100 steps to leave the scene, all far from the surface where a relief of a
// few hundredths cannot matter. So the Voronoi (27 cells) is evaluated only inside a
// BAND around the surface, and its height is faded to zero at the edge of the band
// (a smooth fade keeps the field continuous). Outside the band this costs one
// smoothstep.

float DENSITY = 9.0 * E;   // slider E    // facet density   [4 .. 16]
float DEPTH   = 0.05 * F;   // slider F   // relief depth    [0.02 .. 0.09]  (above ~0.09 rays punch through)

// BAND in field units (like DEPTH): ~10x the depth, never less than 0.3.
float BAND   = max(0.3, 10.0 * DEPTH);
float inBand = 1.0 - smoothstep(0.5 * BAND, BAND, abs(d_surf));

if (inBand > 0.0) {
    vec3 vp = pModel * DENSITY;
    vec3 vi = floor(vp);
    vec3 vf = fract(vp);

    // Voronoi 3x3x3: find the nearest cell-point (F1).
    float f1 = 8.0;
    for (int gx = -1; gx <= 1; gx++)
    for (int gy = -1; gy <= 1; gy++)
    for (int gz = -1; gz <= 1; gz++) {
        vec3 g = vec3(float(gx), float(gy), float(gz));
        // pseudo-random feature point inside the neighbouring cell (arithmetic
        // hash, no sin(): measured 1.6x faster inside map())
        vec3 p3 = fract((vi + g) * vec3(0.1031, 0.1030, 0.0973));
        p3 += dot(p3, p3.yxz + 33.33);
        vec3 o = fract((p3.xxy + p3.yxx) * p3.zyx);
        vec3 r = g + o - vf;
        float d = dot(r, r);   // squared distance (cheaper)
        f1 = min(f1, d);
    }
    f1 = sqrt(f1);   // ~[0,1]: 0 at the cell centre, grows toward the edges

    // Each facet is a cone: high at the cell centre, dropping to the edges (micro-pyramids).
    float facet = 1.0 - f1;

    d_surf -= DEPTH * facet * inBand;
}

// Anti-punch-through trick: slow the rays so they don't overshoot the tips.
d_surf *= 0.6;
